mapper.select:
select t.dimension_id, coalesce(max(c.customer_name), concat('客户#', t.dimension_id)) as dimension_name, ifnull(sum(t.not_due_amount), 0) as not_due_amount, ifnull(sum(t.days_0_30_amount), 0) as days_0_30_amount, ifnull(sum(t.days_31_60_amount), 0) as days_31_60_amount, ifnull(sum(t.days_61_90_amount), 0) as days_61_90_amount, ifnull(sum(t.days_90_above_amount), 0) as days_90_above_amount, ifnull(sum(t.credit_balance), 0) as credit_balance, ifnull(sum(t.net_balance), 0) as net_balance from ( select r.customer_id as dimension_id, case when r.amount > 0 and (r.due_date is null or datediff(curdate(), r.due_date) < 0) then r.amount - ifnull(r.received_amount, 0) - ifnull(r.bad_debt_amount, 0) else 0 end as not_due_amount, case when r.amount > 0 and datediff(curdate(), r.due_date) between 0 and 30 then r.amount - ifnull(r.received_amount, 0) - ifnull(r.bad_debt_amount, 0) else 0 end as days_0_30_amount, case when r.amount > 0 and datediff(curdate(), r.due_date) between 31 and 60 then r.amount - ifnull(r.received_amount, 0) - ifnull(r.bad_debt_amount, 0) else 0 end as days_31_60_amount, case when r.amount > 0 and datediff(curdate(), r.due_date) between 61 and 90 then r.amount - ifnull(r.received_amount, 0) - ifnull(r.bad_debt_amount, 0) else 0 end as days_61_90_amount, case when r.amount > 0 and datediff(curdate(), r.due_date) > 90 then r.amount - ifnull(r.received_amount, 0) - ifnull(r.bad_debt_amount, 0) else 0 end as days_90_above_amount, case when r.amount < 0 then r.amount - ifnull(r.received_amount, 0) - ifnull(r.bad_debt_amount, 0) else 0 end as credit_balance, (r.amount - ifnull(r.received_amount, 0) - ifnull(r.bad_debt_amount, 0)) as net_balance from fin_receivable r where r.biz_status = 'confirmed'
and r.customer_id = #{customerId}
union all select rc.customer_id as dimension_id, 0 as not_due_amount, 0 as days_0_30_amount, 0 as days_31_60_amount, 0 as days_61_90_amount, 0 as days_90_above_amount, -greatest(rc.amount - ifnull(wo.used_amt, 0), 0) as credit_balance, -greatest(rc.amount - ifnull(wo.used_amt, 0), 0) as net_balance from fin_receipt rc left join ( select receipt_id, sum(amount) as used_amt from fin_write_off where status = '1' group by receipt_id ) wo on wo.receipt_id = rc.receipt_id where rc.status = '1' and rc.receivable_id is null and rc.amount > 0 and rc.customer_id is not null and (rc.amount - ifnull(wo.used_amt, 0)) > 0
and rc.customer_id = #{customerId}
) t left join md_customer c on t.dimension_id = c.customer_id group by t.dimension_id

select t.dimension_id, coalesce(max(s.supplier_name), concat('供应商#', t.dimension_id)) as dimension_name, ifnull(sum(t.not_due_amount), 0) as not_due_amount, ifnull(sum(t.days_0_30_amount), 0) as days_0_30_amount, ifnull(sum(t.days_31_60_amount), 0) as days_31_60_amount, ifnull(sum(t.days_61_90_amount), 0) as days_61_90_amount, ifnull(sum(t.days_90_above_amount), 0) as days_90_above_amount, ifnull(sum(t.credit_balance), 0) as credit_balance, ifnull(sum(t.net_balance), 0) as net_balance from ( select p.supplier_id as dimension_id, case when p.amount > 0 and (p.due_date is null or datediff(curdate(), p.due_date) < 0) then p.amount - ifnull(p.paid_amount, 0) else 0 end as not_due_amount, case when p.amount > 0 and datediff(curdate(), p.due_date) between 0 and 30 then p.amount - ifnull(p.paid_amount, 0) else 0 end as days_0_30_amount, case when p.amount > 0 and datediff(curdate(), p.due_date) between 31 and 60 then p.amount - ifnull(p.paid_amount, 0) else 0 end as days_31_60_amount, case when p.amount > 0 and datediff(curdate(), p.due_date) between 61 and 90 then p.amount - ifnull(p.paid_amount, 0) else 0 end as days_61_90_amount, case when p.amount > 0 and datediff(curdate(), p.due_date) > 90 then p.amount - ifnull(p.paid_amount, 0) else 0 end as days_90_above_amount, case when p.amount < 0 then p.amount - ifnull(p.paid_amount, 0) else 0 end as credit_balance, (p.amount - ifnull(p.paid_amount, 0)) as net_balance from fin_payable p where p.biz_status = 'confirmed'
and p.supplier_id = #{supplierId}
union all select pm.supplier_id as dimension_id, 0 as not_due_amount, 0 as days_0_30_amount, 0 as days_31_60_amount, 0 as days_61_90_amount, 0 as days_90_above_amount, -greatest(pm.amount - ifnull(wo.used_amt, 0), 0) as credit_balance, -greatest(pm.amount - ifnull(wo.used_amt, 0), 0) as net_balance from fin_payment pm left join ( select payment_id, sum(amount) as used_amt from fin_write_off where status = '1' group by payment_id ) wo on wo.payment_id = pm.payment_id where pm.status = '1' and pm.payable_id is null and pm.amount > 0 and pm.supplier_id is not null and (pm.amount - ifnull(wo.used_amt, 0)) > 0
and pm.supplier_id = #{supplierId}
) t left join md_supplier s on t.dimension_id = s.supplier_id group by t.dimension_id

select t.dimension_id, coalesce(max(c.customer_name), concat('客户#', t.dimension_id)) as dimension_name, ifnull(sum(t.bill_amount), 0) as bill_amount, ifnull(sum(t.paid_amount), 0) as paid_amount, ifnull(sum(t.diff_amount), 0) as diff_amount from ( select r.customer_id as dimension_id, r.amount as bill_amount, ifnull(r.received_amount, 0) as paid_amount, (r.amount - ifnull(r.received_amount, 0) - ifnull(r.bad_debt_amount, 0)) as diff_amount from fin_receivable r where r.biz_status = 'confirmed'
and r.customer_id = #{customerId}
union all select rc.customer_id as dimension_id, 0 as bill_amount, greatest(rc.amount - ifnull(wo.used_amt, 0), 0) as paid_amount, -greatest(rc.amount - ifnull(wo.used_amt, 0), 0) as diff_amount from fin_receipt rc left join ( select receipt_id, sum(amount) as used_amt from fin_write_off where status = '1' group by receipt_id ) wo on wo.receipt_id = rc.receipt_id where rc.status = '1' and rc.receivable_id is null and rc.amount > 0 and rc.customer_id is not null and (rc.amount - ifnull(wo.used_amt, 0)) > 0
and rc.customer_id = #{customerId}
) t left join md_customer c on t.dimension_id = c.customer_id group by t.dimension_id

select t.dimension_id, coalesce(max(s.supplier_name), concat('供应商#', t.dimension_id)) as dimension_name, ifnull(sum(t.bill_amount), 0) as bill_amount, ifnull(sum(t.paid_amount), 0) as paid_amount, ifnull(sum(t.diff_amount), 0) as diff_amount from ( select p.supplier_id as dimension_id, p.amount as bill_amount, ifnull(p.paid_amount, 0) as paid_amount, (p.amount - ifnull(p.paid_amount, 0)) as diff_amount from fin_payable p where p.biz_status = 'confirmed'
and p.supplier_id = #{supplierId}
union all select pm.supplier_id as dimension_id, 0 as bill_amount, greatest(pm.amount - ifnull(wo.used_amt, 0), 0) as paid_amount, -greatest(pm.amount - ifnull(wo.used_amt, 0), 0) as diff_amount from fin_payment pm left join ( select payment_id, sum(amount) as used_amt from fin_write_off where status = '1' group by payment_id ) wo on wo.payment_id = pm.payment_id where pm.status = '1' and pm.payable_id is null and pm.amount > 0 and pm.supplier_id is not null and (pm.amount - ifnull(wo.used_amt, 0)) > 0
and pm.supplier_id = #{supplierId}
) t left join md_supplier s on t.dimension_id = s.supplier_id group by t.dimension_id
